// Independent implementation: host Node/ICU, UTC only. Never generated by Rooz.
// jalaali-js and Intl intentionally diverge in far-future years; see docs/accuracy.md.
import { writeSync } from 'node:fs';
const formatters = ['persian', 'islamic-civil'].map(calendar => {
  const f = new Intl.DateTimeFormat('en-US-u-nu-latn', {
    calendar, timeZone: 'UTC', year: 'numeric', month: 'numeric', day: 'numeric'
  });
  if (f.resolvedOptions().calendar !== calendar) throw Error(`Missing ICU calendar: ${calendar}`);
  return f;
});
console.error(`Oracle: Node ${process.version}, ICU ${process.versions.icu}, UTC, 1800-01-01..2099-12-31`);
let batch = '';
for (let t = Date.UTC(1800, 0, 1); t < Date.UTC(2100, 0, 1); t += 86400000) {
  const values = formatters.flatMap(f => {
    const p = Object.fromEntries(f.formatToParts(t).map(p => [p.type, p.value]));
    return [p.year, p.month, p.day];
  });
  batch += `${t / 86400000}\t${values.join('\t')}\n`;
  if (batch.length > 65536) { writeSync(1, batch); batch = ''; }
}
if (batch) writeSync(1, batch);
